with kept as (select s.* from orders s where exists (select 1 from shipments c where c.order_id = s.id and c.delivered_date >= s.order_date)) select date_trunc('year', order_date) as year_start, status, percentile_approx(discount, 0.95) as discount_p95, count_if(channel = 'mobile') as mobile_events, count(*) as cnt from kept group by date_trunc('year', order_date), status order by mobile_events nulls first;
